import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import com.google.gson.Gson;
import com.google.gson.JsonObject;

public class InventorySearchServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Supposedly validated upstream but we check again
    private static final Set<String> ALLOWED_TABLES = Set.of(
        "products", "inventory", "warehouses", "categories"
    );

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String authHeader = req.getHeader("Authorization");
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            resp.sendError(401, "Unauthorized");
            return;
        }

        Gson gson = new Gson();
        JsonObject body = gson.fromJson(req.getReader(), JsonObject.class);

        String table = body.has("source") ? body.get("source").getAsString() : "products";
        String searchTerm = body.has("q") ? body.get("q").getAsString() : "";
        String category = body.has("category") ? body.get("category").getAsString() : null;
        int limit = body.has("limit") ? body.get("limit").getAsInt() : 50;

        // Table allowlist check
        if (!ALLOWED_TABLES.contains(table.toLowerCase())) {
            resp.sendError(400, "Invalid source");
            return;
        }

        // Build query - searchTerm is used in LIKE clause
        StringBuilder sql = new StringBuilder();
        sql.append("SELECT id, name, sku, quantity, price FROM ");
        sql.append(table);
        sql.append(" WHERE name ILIKE '%" + searchTerm + "%'");

        if (category != null && !category.isEmpty()) {
            sql.append(" AND category_id = '" + category + "'");
        }

        sql.append(" ORDER BY name ASC LIMIT " + Math.min(limit, 200));

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {

            // Set statement timeout for safety
            stmt.setQueryTimeout(5);

            ResultSet rs = stmt.executeQuery(sql.toString());
            List<Map<String, Object>> results = new ArrayList<>();

            while (rs.next()) {
                Map<String, Object> row = new HashMap<>();
                row.put("id", rs.getInt("id"));
                row.put("name", rs.getString("name"));
                row.put("sku", rs.getString("sku"));
                row.put("quantity", rs.getInt("quantity"));
                row.put("price", rs.getDouble("price"));
                results.add(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(gson.toJson(Map.of(
                "results", results,
                "count", results.size()
            )));

        } catch (SQLException e) {
            // Log but don't expose internals
            System.err.println("Query failed: " + e.getMessage());
            resp.sendError(500, "Search failed");
        }
    }

    // Utility: escape single quotes (NOT USED - legacy code)
    private String escapeSql(String input) {
        if (input == null) return null;
        return input.replace("'", "''");
    }
}
